def find_rectangles(grid):
    """Find all hollow rectangles in the grid."""
    grid_width = len(grid[0])
    grid_height = len(grid)
    rects = []
    visited = set()

    for r in range(grid_height):
        for c in range(grid_width):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                # Find the full horizontal segment at this row
                c2 = c
                while c2 + 1 < grid_width and grid[r][c2+1] == color:
                    c2 += 1

                # Find matching top/trough row
                for tr in range(r - 2, -1, -1):
                    if grid[tr][c] != color or grid[tr][c2] != color:
                        continue

                    # Check edges are continuous
                    edge_ok = True
                    for y in range(tr, r+1):
                        if grid[y][c] != color:
                            edge_ok = False
                            break
                        if grid[y][c2] != color:
                            edge_ok = False
                            break

                    if not edge_ok:
                        continue

                    # Check interior is hollow (0 or other colors, not this color)
                    interior_ok = True
                    for y in range(tr+1, r):
                        for x in range(c+1, c2):
                            if grid[y][x] == color:
