                    rect_key = (tr, c, r, c2)
                    if rect_key in visited:
                        continue

                    rects.append({
                        'top': tr, 'bottom': r,
                        'left': c, 'right': c2,
                        'color': color
                    })
                    visited.add(rect_key)

    return rects

